package app.yoru.android;
import android.Manifest;import android.annotation.SuppressLint;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.webkit.*;import android.widget.*;import android.content.res.Configuration;
